layers.vertex:
attribute vec3 aO; attribute vec2 aP; attribute float aT, aV; uniform float uTime; varying vec2 vQ; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){ if (aV < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float u = uTime - aT, k = eox(clamp(u/.3, 0., 1.)), R = mix(.08, 0.42, k);
      vU = u; vK = aP.y < -.5 ? 1. : 0.;
      if (aP.y < -.5){                                           // orbit line: flat ring quad in the horizontal plane
        float S = .52; vQ = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, 1.45, -position.y*S), 1.); return; }
      float ang = aP.x + uTime*.45;                                  // one celestial marker, slow orbit
      vec3 c = aO + vec3(cos(ang)*R, 1.45 + .25*(1. - k), sin(ang)*R);
      vec4 mv = viewMatrix*vec4(c, 1.); vec2 q = position.xy; mv.xy += q*.15;
      vQ = q; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uCW; varying vec2 vQ; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float pk = vU < .033 ? 2. : 1. + .8*exp(-max(vU - .033, 0.)*10.);
      vec3 o;
      if (vK > .5){
        // thin orbit line: fine core + narrow soft halo, energy drifting slowly in the shards' direction
        float r = length(vQ), a = atan(vQ.y, vQ.x), R = mix(.08, 0.42, eox(clamp(vU/.3, 0., 1.)));
        float flow = .6 + .4*pow(.5 + .5*sin(a*3. + uTime*1.4), 2.);
        float line = lineCore(r - R, .005)*.75 + exp(-pow((r - R)/.03, 2.))*.18;   // halo: a little brighter
        o = (uCW*line*flow + mix(uCW, vec3(1.), .5)*lineCore(r - R, .0025)*.25*flow)*pk;
        o *= smoothstep(.52, .47, r);
      } else {
        // Sun: a small stable golden disc with a 4-point star flare (icon), soft corona; no wind-blown particles
        vec2 q = vQ; float r = length(q), a = atan(q.y, q.x);
        float disc = smoothstep(.36, .32, r), rim = exp(-pow((r - .34)/.03, 2.));
        float star = pow(max(abs(cos(a*2.)), 0.), 14.)*exp(-r*2.4)*smoothstep(.2, .4, r);          // 4 thin rays
        float corona = exp(-r*r*6.)*.25;
        o = (uCW*(disc*.55 + rim*.9 + star*.9 + corona) + mix(uCW, vec3(1., .96, .85), .65)*(disc*exp(-r*r*18.)*.8 + star*.3))*pk;
        o *= smoothstep(1., .82, r);
      }
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }
